// ===== 설정 (여기만 수정하세요) =====
return [{ json: {
  APP_ID: 'com.lgeha.nuts',   // LG ThinQ 구글플레이 앱 ID
  LANG: 'ko', COUNTRY: 'kr',
  MAX_PAGES: 30,              // 1페이지 = 최신 리뷰 최대 150개 → 30페이지 ≈ 4,500개
  KEEP_STARS: [1, 2, 3, 4, 5], // 남길 별점 (답변 분석은 전체 별점 권장)
  token: null, page: 0,
} }];

// 다음 페이지 요청 본문 만들기 (구글플레이 웹페이지가 쓰는 요청 형식)
const cfg = $('설정').first().json;
const s = $input.first().json;               // 처음엔 설정, 이후엔 '페이지 정리'에서 돌아온 값
const inner = JSON.stringify([null, null, [2, 2, [150, null, s.token || null], null, []], [cfg.APP_ID, 7]]);
return [{ json: { page: s.page || 0, token: s.token || null, freq: JSON.stringify([[['UsvDTd', inner, null, 'generic']]]) } }];

// 응답 1페이지 → 리뷰 목록 + 다음 페이지 토큰
const cfg = $('설정').first().json;
const prev = $('요청 준비').first().json;
const text = String($input.first().json.data || '');
let inner = null, error = '';
try { const outer = JSON.parse(text.substring(5)); inner = outer && outer[0] && outer[0][2] ? JSON.parse(outer[0][2]) : null; }
catch (e) { error = '응답 해석 실패: ' + text.slice(0, 120); }
const pick = (a, p) => p.reduce((x, k) => (x == null ? undefined : x[k]), a);
const toDate = d => d ? new Date(Number(String(d[0]) + String(d[1] || '000').slice(0, 3))).toISOString().slice(0, 10) : '';
const reviews = ((inner && inner[0]) || []).map(r => ({ id: r[0], score: r[2], text: r[4] || '', date: toDate(r[5]),
  thumbsUp: r[6] || 0, version: r[10] || '', replyText: pick(r, [7, 1]) || '', replyDate: toDate(pick(r, [7, 2])) }))
  .filter(r => cfg.KEEP_STARS.includes(r.score));     // 별점 1·2·3만 보관 (메모리 절약)
const token = pick(inner, [1, 1]) || null;
const page = prev.page + 1;
return [{ json: { page, token, more: !!token && page < cfg.MAX_PAGES && !error, kept: reviews.length, error, reviews } }];

// 모든 페이지 결과 합치기 (반복 실행된 '페이지 정리' 노드의 각 회차 결과를 모음)
const all = [], seen = new Set();
let runs = 0, lastError = '';
for (let run = 0; run < 200; run++) {
  let items;
  try { items = $('페이지 정리').all(0, run); } catch (e) { break; }
  if (!items || !items.length) break;
  runs++;
  for (const it of items) {
    if (it.json.error) lastError = it.json.error;
    for (const r of (it.json.reviews || [])) if (!seen.has(r.id)) { seen.add(r.id); all.push(r); }
  }
}
return [{ json: { reviews: all, keepStars: $('설정').first().json.KEEP_STARS, pagesRead: runs, lastError } }];

// 리뷰별 LG 답변 정리: 답변 여부·걸린 일수·답변 유형·템플릿 여부 + 리뷰 문제 유형
const { reviews } = $input.first().json;
const TOPICS = {
  '기기 연결·등록': /연결|등록|페어링|와이파이|wi-?fi|공유기|네트워크|오프라인/i, '원격제어 안 됨': /원격|제어|조작|안\s*켜|안\s*꺼|반응\s*(이\s*)?없/,
  '앱 먹통·서버': /먹통|로딩|튕|서버|접속|점검|강제\s*종료|안\s*열|오류|에러|느려|느림/, '로그인·약관': /로그인|계정|인증|비밀번호|비번|약관|동의/,
  '업데이트 후 문제': /업데이트|업뎃|버전/, '알림': /알림|푸시|알람/, '스마트진단': /진단/, '루틴·예약': /루틴|자동화|예약/,
  '1:1 문의·상담': /1\s*:\s*1|문의|고객\s*센터|상담|as|a\/s|서비스\s*센터/i };
const TYPE = { '재설치·재시작 안내': /재설치|삭제\s*후|다시\s*설치|재시작|재실행|종료\s*후|껐다|재부팅|캐시|업데이트\s*후\s*이용|최신\s*버전/,
  '1:1 문의·고객센터 안내': /1\s*:\s*1|1544|고객\s*센터|서비스\s*센터|상담|문의\s*(주시|해\s*주|부탁|바랍|하기)/, '원인 설명': /원인|때문|으로\s*인해|현상은|발생(하|되|할)/,
  '조치 방법 안내': /설정에서|설정\s*(메뉴|화면)|버튼을|눌러|선택해|공유기|2\.4|권한|모델명|위치\s*정보/, '개선·전달 약속': /전달|개선|검토|반영|노력/, '사과': /죄송|불편을\s*드려|양해/, '점검·장애 안내': /점검|장애|일시적|복구/ };
const tags = (t, M) => Object.entries(M).filter(([, re]) => re.test(t)).map(([k]) => k).join(', ');
const norm = t => t.replace(/^[^,]{0,30}님[,\s]*/, '').replace(/^안녕하세요[^.]*\.\s*/, '').replace(/https?:\/\/\S+/g, '[링크]').replace(/\d+/g, '#').slice(0, 60);
const rows = reviews.map(r => {
  const t = String(r.text).replace(/\s+/g, ' ').trim(), rep = String(r.replyText || '').replace(/\s+/g, ' ').trim();
  const days = rep && r.replyDate && r.date ? Math.round((new Date(r.replyDate) - new Date(r.date)) / 864e5) : '';
  return { '별점': r.score, '작성일': r.date, '리뷰내용': t, '문제유형': tags(t, TOPICS), '에어컨언급': /에어컨|에어콘|휘센/.test(t) ? 'Y' : '',
    'LG 답변 여부': rep ? 'Y' : '', 'LG 답변 내용': rep, 'LG 답변일': rep ? r.replyDate : '', '답변까지 걸린 일수': days,
    '답변 유형': rep ? tags(rep, TYPE) : '', '답변 문구 키(템플릿 비교용)': rep ? norm(rep) : '', '도움돼요': r.thumbsUp, '앱버전': r.version, '리뷰ID': r.id };
});
const cnt = new Map(); for (const r of rows) { const k = r['답변 문구 키(템플릿 비교용)']; if (k) cnt.set(k, (cnt.get(k) || 0) + 1); }
for (const r of rows) { const k = r['답변 문구 키(템플릿 비교용)']; r['같은 문구 사용 횟수'] = k ? cnt.get(k) : ''; }
rows.sort((a, b) => a['별점'] - b['별점'] || String(b['작성일']).localeCompare(String(a['작성일'])));
return rows.map(r => ({ json: r }));

// 요약표: 별점별 답변률, 응답 시간, 답변 유형, 문제 유형별 답변률, 자주 쓰인 답변 문구
const rows = $input.all().map(i => i.json);
const pct = (a, b) => b ? Math.round(a / b * 1000) / 10 + '%' : '-';
const out = [], add = (구분, 항목, 값, 비율 = '') => out.push({ json: { 구분, 항목, 값, 비율 } });
const ans = rows.filter(r => r['LG 답변 여부'] === 'Y');
add('기본', '수집 리뷰 수', rows.length); add('기본', 'LG 답변이 달린 리뷰', ans.length, pct(ans.length, rows.length));
for (const s of [1, 2, 3, 4, 5]) { const L = rows.filter(r => r['별점'] === s); if (L.length) add('별점별 답변률', `${s}점 (${L.length}건)`, L.filter(r => r['LG 답변 여부'] === 'Y').length, pct(L.filter(r => r['LG 답변 여부'] === 'Y').length, L.length)); }
const d = ans.map(r => Number(r['답변까지 걸린 일수'])).filter(n => !isNaN(n) && n >= 0).sort((a, b) => a - b);
add('응답 시간', '중앙값(일)', d.length ? d[Math.floor(d.length / 2)] : '-'); add('응답 시간', '3일 이내', d.filter(n => n <= 3).length, pct(d.filter(n => n <= 3).length, d.length));
for (const t of ['재설치·재시작 안내', '1:1 문의·고객센터 안내', '원인 설명', '조치 방법 안내', '개선·전달 약속', '점검·장애 안내', '사과']) { const c = ans.filter(r => r['답변 유형'].includes(t)).length; add('답변 유형(중복)', t, c, pct(c, ans.length)); }
const generic = ans.filter(r => !r['답변 유형'].includes('원인 설명') && !r['답변 유형'].includes('조치 방법 안내')).length;
add('답변 유형(중복)', '원인·구체 조치 없는 답변', generic, pct(generic, ans.length));
for (const t of ['앱 먹통·서버', '기기 연결·등록', '로그인·약관', '업데이트 후 문제', '원격제어 안 됨', '스마트진단', '1:1 문의·상담']) { const L = rows.filter(r => r['문제유형'].includes(t) && r['별점'] <= 3); add('문제 유형별 답변률(1~3점)', `${t} (${L.length}건)`, L.filter(r => r['LG 답변 여부'] === 'Y').length, pct(L.filter(r => r['LG 답변 여부'] === 'Y').length, L.length)); }
const rep = ans.filter(r => Number(r['같은 문구 사용 횟수']) >= 3).length; add('템플릿', '3번 이상 쓰인 같은 문구로 시작하는 답변', rep, pct(rep, ans.length));
const cnt = new Map(); for (const r of ans) { const k = r['답변 문구 키(템플릿 비교용)']; cnt.set(k, (cnt.get(k) || 0) + 1); }
[...cnt].sort((a, b) => b[1] - a[1]).slice(0, 15).forEach(([k, n], i) => add('자주 쓰인 답변 문구', `${i + 1}위: ${k}`, n, pct(n, ans.length)));
return out;
